\begin{ex}%[7D7V4]
Thu gọn đa thức $x^{2}-\left(- 2 x - 1\right) \left(10 x + 5\right)$
\choice
{ \True ${21 x^{2} + 20 x + 5}$ }
   { ${21 x^{2} + 5}$ }
     { ${21 x^{2} + 20 x - 5}$ }
    { ${- 19 x^{2} + 20 x + 5}$ }
\loigiai{
$x^{2}-\left(- 2 x - 1\right) \left(10 x + 5\right)=21 x^{2} + 20 x + 5$
}\end{ex}

\begin{ex}%[7D7V4]
Thu gọn đa thức $- x^{2}-\left(8 - x\right) \left(2 x - 1\right)$
\choice
{ ${x^{2} + 15 x + 8}$ }
   { ${x^{2} - 17 x - 8}$ }
     { ${- 3 x^{2} - 17 x + 8}$ }
    { \True ${x^{2} - 17 x + 8}$ }
\loigiai{
Thực hiện biến đổi đại số/hình học từ các dữ kiện đề bài và đối chiếu điều kiện xác định, ta thu được kết quả: ${x^{2} - 17 x + 8}$.
}\end{ex}

\begin{ex}%[7D7V4]
Thu gọn đa thức $8 x^{2}-\left(7 - 2 x\right) \left(x + 5\right)$
\choice
{ ${6 x^{2} + 3 x - 35}$ }
   { ${10 x^{2} + 3 x + 35}$ }
     { \True ${10 x^{2} + 3 x - 35}$ }
    { ${10 x^{2} + 17 x - 35}$ }
\loigiai{
$8 x^{2}-\left(7 - 2 x\right) \left(x + 5\right)=10 x^{2} + 3 x - 35$
}\end{ex}

\begin{ex}%[7D7V4]
